using System;using System.IO;using System.Linq;using System.Xml;using System.Text;using System.Collections.Generic;using BeamScheduleFormatter;
class PowSourceFilesTests {
 static int checks;static void Check(bool ok,string why){checks++;if(!ok)throw new Exception(why);}static void Reject(Action action,string why){bool failed=false;try{action();}catch{failed=true;}Check(failed,why);}static XmlDocument Doc(string xml="<ProgramOfWorks />"){var doc=new XmlDocument{XmlResolver=null};doc.LoadXml(xml);return doc;}
 static void Main(){string dir=Path.Combine(Path.GetTempPath(),"DTCE-source-test-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);try{
 byte[] dxf=Encoding.Unicode.GetPreamble().Concat(Encoding.Unicode.GetBytes("0\r\nSECTION\r\n2\r\nENTITIES\r\n999\r\nDrawing ñ / GB-1\r\n0\r\nENDSEC\r\n0\r\nEOF\r\n")).ToArray();byte[] binary=Enumerable.Range(0,512).Select(i=>(byte)i).ToArray();string drawing=Path.Combine(dir,"Beam drawing.dxf"),reference=Path.Combine(dir,"Reference.pdf");File.WriteAllBytes(drawing,dxf);File.WriteAllBytes(reference,binary);var source=new PowSourceFiles();source.CaptureFile(drawing,"Beam DXF");source.CaptureFile(reference,"Project attachment");Check(source.Files.Count==2,"Both DXF and arbitrary imported binary retained");Check(source.Files.Single(f=>f.Name.EndsWith("dxf")).Text().Contains("ñ / GB-1"),"DXF decoding recognizes original BOM");source.CaptureFile(drawing,"Beam DXF");Check(source.Files.Count==2,"Repeated same file deduplicates");var doc=Doc();source.Write(doc.DocumentElement,true);source.Write(doc.DocumentElement);string path=Path.Combine(dir,"Project.pow.xml");doc.Save(path);File.Delete(drawing);File.Delete(reference);doc.Load(path);var restored=PowSourceFiles.Read(doc.DocumentElement);Check(restored.Files.Count==2,"Whole archive opens after original files deleted");Check(restored.Files.Single(f=>f.Name=="Beam drawing.dxf").Bytes().SequenceEqual(dxf),"Original DXF bytes, BOM and line endings preserved exactly");Check(restored.Files.Single(f=>f.Name=="Reference.pdf").Bytes().SequenceEqual(binary),"Arbitrary binary source preserved exactly");Check(!doc.OuterXml.Contains(dir),"Absolute source paths are not persisted");Check(doc.SelectSingleNode("//SourceFiles/File").InnerText.Length>0,"Payload is stored inside POW, not an external path");
 var old=Doc();Check(PowSourceFiles.Read(old.DocumentElement).Files.Count==0,"Earlier POW without attachments remains compatible");var textCopy=new PowSourceFiles();textCopy.CaptureText("Beam drawing.dxf","Beam DXF","Imported text");Check(textCopy.Files.Single().RecoveredText,"Old embedded DXF text identified as recovered");textCopy.Add(restored.Files.Single(f=>f.Name=="Beam drawing.dxf"));Check(textCopy.Files.Count==1&&!textCopy.Files.Single().RecoveredText,"Exact original replaces derived text copy");textCopy.CaptureText("Beam drawing.dxf","Beam DXF","Imported text");Check(textCopy.Files.Count==1,"Restoring schedule text does not overwrite original bytes");textCopy.Add(new PowSourceFile("Beam drawing.dxf","Beam DXF",new byte[]{3,4,5}));Check(textCopy.Files.Count==2,"Same filename with different content retained as a separate revision");
 var corrupt=Doc(doc.OuterXml);((XmlElement)corrupt.SelectSingleNode("//SourceFiles/File")).SetAttribute("sha256",new string('0',64));Reject(()=>PowSourceFiles.Read(corrupt.DocumentElement),"Corrupt file checksum rejected before restoration");corrupt=Doc(doc.OuterXml);((XmlElement)corrupt.SelectSingleNode("//SourceFiles/File")).SetAttribute("size","1");Reject(()=>PowSourceFiles.Read(corrupt.DocumentElement),"Compressed payload expansion beyond declared size rejected");corrupt=Doc(doc.OuterXml);((XmlElement)corrupt.SelectSingleNode("//SourceFiles/File")).SetAttribute("name","../escape.dxf");Reject(()=>PowSourceFiles.Read(corrupt.DocumentElement),"Archived path traversal rejected");corrupt=Doc(doc.OuterXml);corrupt.DocumentElement.RemoveChild(corrupt.DocumentElement["SourceFiles"]);Reject(()=>PowSourceFiles.Read(corrupt.DocumentElement),"Missing payload cannot silently satisfy nonempty manifest");corrupt=Doc(doc.OuterXml);corrupt.SelectSingleNode("//SourceFiles").AppendChild(corrupt.SelectSingleNode("//SourceFiles/File").CloneNode(true));Reject(()=>PowSourceFiles.Read(corrupt.DocumentElement),"Duplicate attachment records rejected");Reject(()=>new PowSourceFile("bad?.dxf","Beam DXF",new byte[0]),"Unsafe Windows filename rejected on every host");Check(new PowSourceFile(@"C:\work\floor\A.dxf","Beam DXF",new byte[0]).Name=="A.dxf","Only filename retained from Windows source path");byte[] exposed=restored.Files[0].Bytes();byte saved=exposed[0];exposed[0]^=1;Check(restored.Files[0].Bytes()[0]==saved,"Source bytes cannot be changed through returned buffer");
 var a=new ScheduleSource{Label="Ground | Renamed.dxf",Rows=new Dictionary<string,BeamRow>(StringComparer.OrdinalIgnoreCase){{"GB-1",new BeamRow{Mark="GB-1"}}}};var b=new ScheduleSource{Label="Roof | Roof.dxf",Rows=new Dictionary<string,BeamRow>(StringComparer.OrdinalIgnoreCase){{"3B-1",new BeamRow{Mark="3B-1"}}}};var savedEntries=Doc("<BeamEstimate><Entry schedule='old missing label' mark=' gb–1 '/><Entry schedule='old' mark=''/><Entry schedule='missing floor' mark='UNKNOWN-9' length='4' quantity='3'/><Entry schedule='Wrong existing floor' mark='3B-1'/></BeamEstimate>");PowBeamEntrySources.RestoreReferences(savedEntries.DocumentElement,new[]{a,b});var entries=savedEntries.SelectNodes("//Entry").Cast<XmlElement>().ToArray();Check(entries[0].GetAttribute("mark")=="GB-1"&&entries[0].GetAttribute("schedule")==a.Label,"Unique normalized beam mark repairs stale source label");Check(entries[1].GetAttribute("schedule")==a.Label&&entries[1].GetAttribute("mark")=="","Blank pending beam row can reopen");Check(entries[2].GetAttribute("mark")=="UNKNOWN-9"&&entries[2].GetAttribute("quantity")=="3","Unresolved beam inputs retained rather than aborting or changing quantity");Check(entries[3].GetAttribute("schedule")==b.Label,"Existing wrong source label repaired by actual unique mark");Reject(()=>PowBeamEntrySources.RestoreReferences(Doc("<BeamEstimate><Entry mark='GB-1'/></BeamEstimate>").DocumentElement,new[]{a,a}),"Ambiguous duplicate source mark is not guessed");Console.WriteLine("PASS: "+checks+" original-file archive, recovery, integrity and beam-source reference checks");
 }finally{Directory.Delete(dir,true);}}
}
